import{_ as i,C as t,o as n,c as s,E as a,a2 as l}from"./chunks/framework.VWKgVqrc.js";const m=JSON.parse('{"title":"批准一次动作，尚未说明谁有权委派","description":"","frontmatter":{"title":"批准一次动作，尚未说明谁有权委派","article_type":"engineering-insight","edition":"research-center","research_question":"动作前的人工批准能说明什么，委派权限还需要哪些证据？","summary":"固定版本的局部函数探针可以说明批准怎样改变动作，却不能替代调用者身份、权限范围和规则覆盖的证据。","sources":"Salesforce Help; MCP draft authorization and security guidance; AgentSpec v3 and pinned source","date":"2026-11-12","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261112-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-12-sig-20261112-002-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-12-sig-20261112-002.md","filePath":"zh/industry/2026-11-12-sig-20261112-002.md","lastUpdated":null}'),d={name:"zh/industry/2026-11-12-sig-20261112-002.md"};function c(p,e,h,u,f,g){const r=t("ArticleCover"),o=t("ArticleTableScroll");return n(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-11-12-sig-20261112-002-cover.png",kicker:"研究成果",title:"批准一次动作，尚未说明谁有权委派",summary:"固定版本的局部函数探针可以说明批准怎样改变动作，却不能替代调用者身份、权限范围和规则覆盖的证据。",version:"2026-11-12",languageHref:"/en/industry/2026-11-12-sig-20261112-002",languageLabel:"English"}),a(o,{language:"zh"}),e[0]||(e[0]=l('<h1 id="批准一次动作-尚未说明谁有权委派" tabindex="-1">批准一次动作，尚未说明谁有权委派 <a class="header-anchor" href="#批准一次动作-尚未说明谁有权委派" aria-label="Permalink to &quot;批准一次动作，尚未说明谁有权委派&quot;">​</a></h1><p>一次人工批准之后，执行器继续的是原来的动作。这是一个可以通过代码检验的具体承诺；“这次委派调用已获得正确授权”则还涉及谁发起调用、批准覆盖什么范围，以及动作是否经过相应检查。两者之间不能只用一个确认框连接。</p><p>本次研究把这条边界落到一个有限的执行结果上：在固定版本的 AgentSpec（智能体动作约束框架）局部函数中，同意会继续原动作，拒绝会跳过；空规则和未触发的规则仍保留原动作。我们的判断是，动作批准、规则覆盖与调用者权限需要分别取证。这个结果既不认证完整平台的安全性，也不构成对某个已部署产品的绕过指控。[1][2]</p><h2 id="确认之后-究竟继续了什么" tabindex="-1">确认之后，究竟继续了什么 <a class="header-anchor" href="#确认之后-究竟继续了什么" aria-label="Permalink to &quot;确认之后，究竟继续了什么&quot;">​</a></h2><p>已读源码中的同步执行路径先调用约束检查，再进入实际动作执行。人工检查函数接收动作，询问用户并返回相应结果。本次研究分析已在固定提交上抽取并执行所选函数；这是登记基线版本，不是对当前最新代码或论文发布包的认定。[1]</p><p>内部实验依据的范围很窄：五个人工回答用例，以及六个规则分派用例。动作、规则、规则解释器和状态使用明确披露的测试替身；真实领域谓词、适配器以及 LangChain（智能体应用框架）均未运行。它检验的是分支行为，不是完整系统复现。[2]</p><table tabindex="0"><thead><tr><th>输入或条件</th><th>内部探针观察到的结果</th><th>能支持的判断</th></tr></thead><tbody><tr><td>回答 yes，或带空白的 y</td><td>返回继续，保留同一个动作对象</td><td>本函数的同意分支没有替换动作</td></tr><tr><td>回答 no 或 n</td><td>返回跳过，动作变为跳过对象</td><td>本函数可抑制该动作</td></tr><tr><td>无效回答后再回答 yes</td><td>询问两次，随后继续原动作</td><td>无效输入没有直接放行</td></tr><tr><td>已触发规则，解释结果分别为继续、跳过、停止</td><td>分别保留动作、转换为跳过、转换为结束</td><td>分派遵循所注入的解释结果</td></tr><tr><td>未触发规则或空规则列表</td><td>保留原动作</td><td>是否阻止动作取决于规则覆盖与触发</td></tr><tr><td>规则值缺失</td><td>抛出规则不得为空值的异常</td><td>空列表与缺失规则不是同一种路径</td></tr></tbody></table><p>表中结果均来自本次研究的内部隔离函数探针，不是第三方独立验证，也不是用户真实调用样本。解释器的继续、跳过和停止结果由替身提供，因此不能从分派正确推论实际谓词也正确。[2]</p><p>保留同一个动作对象，只能说明这次同步函数调用的返回关系。它没有测量并发修改、批准后的对象变化、异步调用或恢复执行。把“原对象继续”写成“批准内容与最终执行内容始终一致”，会超出实验。</p><h2 id="检查存在-不等于规则已经覆盖" tabindex="-1">检查存在，不等于规则已经覆盖 <a class="header-anchor" href="#检查存在-不等于规则已经覆盖" aria-label="Permalink to &quot;检查存在，不等于规则已经覆盖&quot;">​</a></h2><p>空规则与未触发规则是必要的对照。它们说明执行路径存在检查调用，并不意味着每个需要约束的动作都被某条有效规则拦住。要判断一个动作受到什么保护，仍需找到适用规则、触发条件、谓词读取的状态，以及最终执行点。这里只执行了其中很小的一段。</p><p>AgentSpec 的论文将机制描述为触发、谓词与执行约束，并讨论动作、状态和结束边界；论文记录的实现对接框架版本为 0.3.13。公开机制描述支持“应检查哪些位置”的讨论，不能自动补足未审计解释器、领域适配器或异步路径的证据。[3]</p><p>论文还报告了约束的代价与覆盖差异：其具身任务中的安全任务完成率从 58.62% 降至 54.26%；自动生成规则在八项驾驶违规中阻止五项，而手工规则在所测场景中取得完全合规。这些是作者报告的指定实验结果，未由我们重跑；它们提醒读者把规则选择视为待评估对象，而不能把“有约束机制”直接读成“所有任务都会安全完成”。[3]</p><h2 id="组织关系、令牌与批准回答各管什么" tabindex="-1">组织关系、令牌与批准回答各管什么 <a class="header-anchor" href="#组织关系、令牌与批准回答各管什么" aria-label="Permalink to &quot;组织关系、令牌与批准回答各管什么&quot;">​</a></h2><p>Salesforce（企业软件供应商）的帮助文章描述了同组织内由父级规划者委派、跨组织的明确关系，以及网关按智能体提供控制等能力。这些是供应商的能力描述；所读材料没有给出足以验证本次委派凭据范围、令牌传播链或实际执行结果的数据。不能从组织关系推断每一次工具调用的权限已经得到验证。[4]</p><p>MCP（模型上下文协议）的已捕获授权草案处理另一层责任。授权在该草案中是可选能力；基于 HTTP（超文本传输协议）的实现若支持授权，应遵循相应流程，STDIO（标准输入输出传输）则应从环境取得凭据。对采用该授权流程的请求，资源服务器需要验证令牌面向自己的受众；安全条款还要求上游接口使用单独令牌，禁止直接透传客户端令牌。[5][6]</p><p>同一组安全指导把状态句柄归为普通工具参数：它不能用来认证调用者，应在服务器端绑定到已经验证的主体。猜中一个流程句柄，不应就能操作另一个用户的状态。这是一项规范要求，不是对任何具体服务已经正确实现的测量。[7]</p><p>这些材料可以放在一起比较责任，却不能拼成一次不存在的集成测试：组织关系说明如何建立协作；令牌受众与上游凭据限制说明资源边界；状态绑定说明谁拥有某份状态；人工回答则决定所见检查点上的动作走向。只有最后一项在本轮执行了局部分支探针。其他层面的规定或描述不能替它提供执行证据，局部探针也不能反过来验证其他层面。</p><p>由此得到的工程解释是：评审一条委派调用时，应分别追问调用主体如何确认、动作及资源范围如何限定、批准对应哪一次动作，以及所有实际执行路径是否经过适用规则。这是根据现有证据提出的检查方向，不是一个已经实现或验证的完整授权方案。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的公开一手事实说明规范或固定源码写了什么；来源陈述保留供应商与论文作者的归属；本次观察与内部实验依据只覆盖所读代码和所执行的局部函数；研究解释提出需要分开核验的责任。没有独立第三方检验本文所讨论的完整委派链。引用不等于背书，同行评审不等于证明，来源自报不等于独立证据；论文发表或实现成功也不建立普遍有效性。</p><ol><li>AgentSpec 作者，固定版本的受约束执行器及人工检查源码，2026-11-12 已读本地快照。登记基线提交：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e6fa3902e2cfb9681f454b355691b771f70543f8</span></span></code></pre></div><p><a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/controlled_agent_excector.py" target="_blank" rel="noreferrer">执行器源码</a>；<a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/enforcement.py" target="_blank" rel="noreferrer">人工检查源码</a>。 2. 本研究中心，<a href="/joinwell52/assets/evidence/2026-11-12-sig-20261112-002/002-experiment.json">2026-11-12 内部隔离函数实验记录</a>：五个人工回答、六个规则分派用例。实验替身、输入、输出与边界保存在同日研究对象所绑定的实验记录中；不是公开产品测试或第三方复现。 3. AgentSpec 作者，《面向安全可靠大语言模型智能体的可定制运行时约束》，研究论文，版本 v3，动作约束机制及实验表 4–6，2026-11-12 已读快照。<a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">论文</a>。 4. Salesforce，帮助文档，关于同组织、多组织协作与智能体网关的说明，2026-11-12 已读快照。<a href="https://help.salesforce.com/s/articleView?id=005317683&amp;language=en_US&amp;type=1" target="_blank" rel="noreferrer">帮助文章</a>。 5. MCP 项目，授权规范草案，范围、协议要求与令牌处理，2026-11-12 已捕获版本；草案可变。<a href="https://modelcontextprotocol.io/specification/draft/basic/authorization.md" target="_blank" rel="noreferrer">授权规范</a>。 6. MCP 项目，授权安全条款草案，令牌受众绑定与权限限制，2026-11-12 已捕获版本。<a href="https://modelcontextprotocol.io/specification/draft/basic/authorization/security-considerations.md" target="_blank" rel="noreferrer">安全条款</a>。 7. MCP 项目，安全最佳实践草案，状态句柄劫持条目，2026-11-12 已捕获版本。<a href="https://modelcontextprotocol.io/docs/draft/tutorials/security/security_best_practices.md" target="_blank" rel="noreferrer">安全指导</a>。</p><h2 id="单用户检查可以足够-分布式证据仍待补齐" tabindex="-1">单用户检查可以足够，分布式证据仍待补齐 <a class="header-anchor" href="#单用户检查可以足够-分布式证据仍待补齐" aria-label="Permalink to &quot;单用户检查可以足够，分布式证据仍待补齐&quot;">​</a></h2><p>一个同步、本地、单用户的人工检查点可能完全符合其威胁模型。不能因为所读文件没有分布式批准凭据，就断言完整系统缺少这类控制；也不能把本实验未测试的路径写成漏洞。</p><p>目前仍未建立的，是子动作与发起主体、任务实例和批准实例如何绑定，长期委派中撤销权限如何生效，以及异步、工具内部和恢复路径是否经过相同约束。要回答这些问题，需要相应路径及凭据的实际证据。本轮能够成立的边界停在这里：批准确实改变了所测函数中的动作走向，而委派权限还需要自己的证明材料。</p>',27))])}const _=i(d,[["render",c]]);export{m as __pageData,_ as default};
